    player.planeX = 0; player.planeY = 0.66;

    document.getElementById('audio-warning').style.display = 'none';
    document.getElementById('screen-gameover').classList.add('hidden');
    gameState = 'PLAYING';
    populateEntities();
    lastTime = performance.now();
});

document.getElementById('btn-pause').addEventListener('click', () => {
    if(gameState === 'PLAYING') {
        gameState = 'PAUSED';
        document.getElementById('btn-pause').innerText = "RESUME";
    } else if(gameState === 'PAUSED') {
        gameState = 'PLAYING';
        document.getElementById('btn-pause').innerText = "PAUSE";
        lastTime = performance.now();
    }
});

document.getElementById('btn-mute').addEventListener('click', () => {
    isMuted = !isMuted;
    document.getElementById('btn-mute').innerText = isMuted ? "UNMUTE" : "MUTE";
});

// --- Physics Framework & Updates ---
function updateSimulation(dt) {
    if (player.fireCooldown > 0) player.fireCooldown -= dt;
    if (damageVignetteAlpha > 0) damageVignetteAlpha -= dt * 2.5; // Decays over frames quickly

    // 1. Resolve Rotational Aim vectors
    let turnSpeed = 0;
    if (keys['q'] || keys['arrowleft']) turnSpeed -= 2.4 * dt;
    if (keys['e'] || keys['arrowright']) turnSpeed += 2.4 * dt;
    if (mouseDeltaX !== 0) {
        turnSpeed += mouseDeltaX * 0.0045;
        mouseDeltaX = 0; 
    }

    if (turnSpeed !== 0) {
        let oldDirX = player.dirX;
        player.dirX = player.dirX * Math.cos(turnSpeed) - player.dirY * Math.sin(turnSpeed);
        player.dirY = oldDirX * Math.sin(turnSpeed) + player.dirY * Math.cos(turnSpeed);
        let oldPlaneX = player.planeX;
        player.planeX = player.planeX * Math.cos(turnSpeed) - player.planeY * Math.sin(turnSpeed);
        player.planeY = oldPlaneX * Math.sin(turnSpeed) + player.planeY * Math.cos(turnSpeed);
    }

    // 2. Resolve Translation Matrices
    let moveSpeed = 3.2 * dt;
    let nextX = player.x;
    let nextY = player.y;

    if (keys['w']) { nextX += player.dirX * moveSpeed; nextY += player.dirY * moveSpeed; }
    if (keys['s']) { nextX -= player.dirX * moveSpeed; nextY -= player.dirY * moveSpeed; }
    if (keys['a']) { nextX -= player.planeX * moveSpeed; nextY -= player.planeY * moveSpeed; }
    if (keys['d']) { nextX += player.planeX * moveSpeed; nextY += player.planeY * moveSpeed; }

    if (map[Math.floor(player.y) * MAP_WIDTH + Math.floor(nextX + (nextX > player.x ? 0.25 : -0.25))] === 0) player.x = nextX;
    if (map[Math.floor(nextY + (nextY > player.y ? 0.25 : -0.25)) * MAP_WIDTH + Math.floor(player.x)] === 0) player.y = nextY;

    // Boundary Gate Check Execution Rules
    if (Math.floor(player.x) === EXIT_TILE_X && Math.floor(player.y) === EXIT_TILE_Y) {
        if (player.cellsCollected >= 3) {
            triggerEndgame(true, "Airlock sealed successfully. Containment stabilized.");
            return;
        }
    }

    // 3. Entity Behavior Loop
    entities.forEach(ent => {
        if (!ent.active) return;
        ent.phase += dt * 4.5;

        let dist = Math.hypot(ent.x - player.x, ent.y - player.y);

        if (ent.type === 'cell') {
            if (dist < 0.45) {
                ent.active = false;
                player.cellsCollected++;
                playSound(587.33, 'sine', 0.08, 0.25); 
                setTimeout(() => playSound(783.99, 'sine', 0.15, 0.25), 70);
            }
        } else if (ent.type === 'drone') {
            let vx = player.x - ent.x;
            let vy = player.y - ent.y;
            if (dist > 0.35) {
                let step = ent.speed * dt;
                let targetX = ent.x + (vx / dist) * step;
                let targetY = ent.y + (vy / dist) * step;

                if (map[Math.floor(ent.y) * MAP_WIDTH + Math.floor(targetX)] === 0) ent.x = targetX;
                if (map[Math.floor(targetY) * MAP_WIDTH + Math.floor(ent.x)] === 0) ent.y = targetY;
            }

            if (dist < 0.65) {
                player.health -= 30 * dt;
                damageVignetteAlpha = Math.min(0.7, damageVignetteAlpha + dt * 4.0);
                if(Math.random() < 0.12) playSound(90, 'sawtooth', 0.06, 0.15);
                if (player.health <= 0) {
                    triggerEndgame(false, "System core failure. Vital signs terminated.");
                }
            }
        }
    });
}

function triggerEndgame(isVictory, narrativeText) {
    gameState = 'GAMEOVER';
    document.exitPointerLock?.();

    // Process Dashboard Elements
    document.getElementById('gameover-title').innerText = isVictory ? "MISSION ACCOMPLISHED" : "STATION LOST";
    document.getElementById('gameover-title').style.color = isVictory ? "#00ffcc" : "#ff3366";
    document.getElementById('gameover-reason').innerText = narrativeText;

    // Performance Metrics Table Insertion
    document.getElementById('score-time').innerText = `${Math.floor(elapsedPlayTime)} seconds`;
    document.getElementById('score-health').innerText = `${Math.max(0, Math.ceil(player.health))}%`;
    document.getElementById('score-cells').innerText = `${player.cellsCollected} / 3`;
    document.getElementById('score-drones').innerText = dronesDisabledCount;

    document.getElementById('screen-gameover').classList.remove('hidden');

    if(isVictory) {
        playSound(523.25, 'square', 0.2, 0.2);
        setTimeout(() => playSound(659.25, 'square', 0.2, 0.2), 150);
        setTimeout(() => playSound(987.77, 'square', 0.5, 0.2), 300);
    } else {
        playSound(80, 'sawtooth', 0.9, 0.4);
    }
}

// --- Raycaster Engine Framework & Rendering ---
function renderFrame() {
    const W = canvas.width;
    const H = canvas.height;

    // Sky/Floor Horizon base split
    let bgGrad = ctx.createLinearGradient(0, 0, 0, H);
    bgGrad.addColorStop(0, '#020208');
    bgGrad.addColorStop(0.5, '#0b0a14');
    bgGrad.addColorStop(0.51, '#100f14');
    bgGrad.addColorStop(1, '#040406');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, W, H);

    let zBuffer = new Array(W);

    // 1. Raycast Wall Traversal Engine Loop
    for (let x = 0; x < W; x++) {
        let cameraX = 2 * x / W - 1;
        let rayDirX = player.dirX + player.planeX * cameraX;
        let rayDirY = player.dirY + player.planeY * cameraX;

        let mapX = Math.floor(player.x);
        let mapY = Math.floor(player.y);

        let sideDistX, sideDistY;
        let deltaDistX = (rayDirX === 0) ? Infinity : Math.abs(1 / rayDirX);
        let deltaDistY = (rayDirY === 0) ? Infinity : Math.abs(1 / rayDirY);
        let perpWallDist;

        let stepX, stepY;
        let hit = 0;
        let side; 
        let wallType = 0;

        if (rayDirX < 0) { stepX = -1; sideDistX = (player.x - mapX) * deltaDistX; } 
        else           { stepX = 1; sideDistX = (mapX + 1.0 - player.x) * deltaDistX; }
        if (rayDirY < 0) { stepY = -1; sideDistY = (player.y - mapY) * deltaDistY; } 
        else           { stepY = 1; sideDistY = (mapY + 1.0 - player.y) * deltaDistY; }

        while (hit === 0) {
            if (sideDistX < sideDistY) { sideDistX += deltaDistX; mapX += stepX; side = 0; } 
            else                       { sideDistY += deltaDistY; mapY += stepY; side = 1; }
            if(mapX < 0 || mapX >= MAP_WIDTH || mapY < 0 || mapY >= MAP_HEIGHT) break;
            let tile = map[mapY * MAP_WIDTH + mapX];
            if (tile > 0) { hit = 1; wallType = tile; }
        }

        if (side === 0) perpWallDist = (mapX - player.x + (1 - stepX) / 2) / rayDirX;
        else           perpWallDist = (mapY - player.y + (1 - stepY) / 2) / rayDirY;

        if(perpWallDist <= 0) perpWallDist = 0.01;
        zBuffer[x] = perpWallDist;

        let lineHeight = Math.floor(H / perpWallDist);
        let drawStart = -lineHeight / 2 + H / 2;
        let drawEnd = lineHeight / 2 + H / 2;

        let wallColor = "#1452cc"; 
        if (wallType === 2) wallColor = player.cellsCollected >= 3 ? "#00ff88" : "#ff9900";

        ctx.strokeStyle = wallColor;
        if(side === 1) {
            ctx.strokeStyle = (wallType === 2) ? (player.cellsCollected >= 3 ? "#00b35f" : "#cc7a00") : "#0f3da1";
        }

        let fog = Math.min(1, 1.2 / (1 + perpWallDist * perpWallDist * 0.035));
        ctx.globalAlpha = fog;

        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x, drawStart);
        ctx.lineTo(x, drawEnd);
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // Structural detailing grid lines
        ctx.fillStyle = player.cellsCollected >= 3 && wallType === 2 ? "#00ffcc" : "#00ffff";
        ctx.fillRect(x, drawStart, 1, 2);
        ctx.fillRect(x, drawEnd - 2, 1, 2);
    }

    // 2. Billboard Sprites Layer Mapping
    let sprOrder = entities.map((e, idx) => ({ index: idx, dist: Math.hypot(e.x - player.x, e.y - player.y) }));
    sprOrder.sort((a, b) => b.dist - a.dist);

    sprOrder.forEach(item => {
        let ent = entities[item.index];
        if (!ent.active) return;

        let sprX = ent.x - player.x;
        let sprY = ent.y - player.y;
        let invDet = 1.0 / (player.planeX * player.dirY - player.dirX * player.planeY);
        let transformX = invDet * (player.dirY * sprX - player.dirX * sprY);
        let transformY = invDet * (-player.planeY * sprX + player.planeX * sprY); 

        if (transformY <= 0.1) return; 

        let sprScreenX = Math.floor((W / 2) * (1 + transformX / transformY));
        let sprHeight = Math.abs(Math.floor(H / transformY));
        let sprWidth = sprHeight;

        let drawStartV = -sprHeight / 2 + H / 2;
        let drawEndX = Math.floor(sprWidth / 2 + sprScreenX);
        let drawStartX = Math.floor(-sprWidth / 2 + sprScreenX);

        let bobbing = Math.sin(ent.phase) * (sprHeight * 0.08);

        for (let stripe = drawStartX; stripe < drawEndX; stripe++) {
            if (stripe >= 0 && stripe < W && transformY < zBuffer[stripe]) {
                let localX = (stripe - drawStartX) / sprWidth;

                if (ent.type === 'cell') {
                    ctx.fillStyle = "#00ff88"; 
                    if (Math.abs(localX - 0.5) < 0.16) {
                        ctx.fillRect(stripe, drawStartV + bobbing + (sprHeight * 0.2), 1, sprHeight * 0.6);
                    }
                    if(Math.abs(localX - 0.5) < 0.35 && Math.abs(localX - 0.5) > 0.12) {
                        ctx.fillRect(stripe, drawStartV + bobbing + (sprHeight * 0.4), 1, sprHeight * 0.2);
                    }
                } else if (ent.type === 'drone') {
                    ctx.fillStyle = "#ff2255";
                    if (Math.abs(localX - 0.5) < 0.28) {
                        ctx.fillRect(stripe, drawStartV + bobbing + (sprHeight * 0.25), 1, sprHeight * 0.35);
                        if(Math.abs(localX - 0.5) < 0.08) {
                            ctx.fillStyle = "#ffffff";
                            ctx.fillRect(stripe, drawStartV + bobbing + (sprHeight * 0.32), 1, sprHeight * 0.08);
                        }
                    }
                    ctx.fillStyle = "#444455";
                    if(Math.abs(localX - 0.32) < 0.03 || Math.abs(localX - 0.68) < 0.03) {
                        ctx.fillRect(stripe, drawStartV + bobbing + (sprHeight * 0.45), 1, sprHeight * 0.25);
                    }
                }
            }
        }
    });

    // 3. Shock Pulse Weapon Render Pass
    if (player.isFiring > 0) {
        player.isFiring--;
        let flash = ctx.createRadialGradient(W/2, H - 45, 10, W/2, H - 45, 90);
        flash.addColorStop(0, 'rgba(255,255,255,1)');
        flash.addColorStop(0.4, 'rgba(0,255,204,0.7)');
        flash.addColorStop(1, 'rgba(0,255,204,0)');
        ctx.fillStyle = flash;
        ctx.fillRect(0, 0, W, H);

        ctx.strokeStyle = "rgba(0, 255, 204, 0.5)";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(W/2, H/2 - 8); ctx.lineTo(W/2, H/2 + 8);
        ctx.moveTo(W/2 - 8, H/2); ctx.lineTo(W/2 + 8, H/2);
        ctx.stroke();
    }

    // Rifle Emitter Body Assembly Frame 
    ctx.fillStyle = "#12121c";
    ctx.strokeStyle = "#00ffcc";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(W/2 - 30, H);
    ctx.lineTo(W/2 - 16, H - 65);
    ctx.lineTo(W/2 + 16, H - 65);
    ctx.lineTo(W/2 + 30, H);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = player.fireCooldown > 0 ? "#ff2255" : "#00ffcc";
    ctx.fillRect(W/2 - 3, H - 58, 6, 12);

    ctx.fillStyle = "rgba(0, 255, 204, 0.4)";
    ctx.fillRect(W/2 - 1, H/2 - 1, 2, 2);

    // 4. DAMAGE VIGNETTE RENDER LAYER
    if (damageVignetteAlpha > 0) {
        let dmgGrad = ctx.createRadialGradient(W/2, H/2, H/3, W/2, H/2, W/2);
        dmgGrad.addColorStop(0, 'rgba(255, 0, 50, 0)');
        dmgGrad.addColorStop(1, `rgba(255, 0, 50, ${damageVignetteAlpha})`);
        ctx.fillStyle = dmgGrad;
        ctx.fillRect(0, 0, W, H);
    }

    // 5. HUD Status Ribbon Layout
    ctx.fillStyle = "#000000";
    ctx.fillRect(0, H - 35, W, 35);
    ctx.strokeStyle = "#00ffcc";
    ctx.lineWidth = 1;
    ctx.strokeRect(0, H - 35, W, 35);

    ctx.font = "bold 9px monospace";
    ctx.fillStyle = oxygenTimer <= 30 ? "#ff3366" : "#00ffcc";
    ctx.fillText(`O2 RESERVES: ${Math.ceil(oxygenTimer)}s`, 12, H - 14);

    ctx.fillStyle = player.health <= 35 ? "#ff3366" : "#00ffcc";
    ctx.fillText(`SUIT VITALS: ${Math.max(0, Math.ceil(player.health))}%`, 140, H - 14);

    ctx.fillStyle = "#00ffcc";
    ctx.fillText(`CORES: ${player.cellsCollected}/3`, 255, H - 14);

    // 6. PROCEDURAL INTEGRATED RADAR ARCHITECTURE
    const radarSize = 28;
    const radarCenterX = W - 32;
    const radarCenterY = H - 18;

    // Outer Boundary Ring
    ctx.strokeStyle = "rgba(0, 255, 204, 0.4)";
    ctx.beginPath();
    ctx.arc(radarCenterX, radarCenterY, radarSize, 0, Math.PI * 2);
    ctx.stroke();

    // Directional FOV Sweeper Guidelines
    ctx.strokeStyle = "rgba(0, 255, 204, 0.12)";
    ctx.beginPath();
    ctx.moveTo(radarCenterX - radarSize, radarCenterY); ctx.lineTo(radarCenterX + radarSize, radarCenterY);
    ctx.moveTo(radarCenterX, radarCenterY - radarSize); ctx.lineTo(radarCenterX, radarCenterY + radarSize);
    ctx.stroke();

    // Plot Objective Coordinates Inside Compass Range Space
    entities.forEach(ent => {
        if (!ent.active) return;

        let relX = ent.x - player.x;
        let relY = ent.y - player.y;

        // Project map components onto player orientation space coordinates
        let rotX = relX * player.dirY - relY * player.dirX;
        let rotY = relX * player.dirX + relY * player.dirY;

        // Radar scaling compression parameter multiplier factor
        let pX = radarCenterX + rotX * 3.5;
        let pY = radarCenterY - rotY * 3.5;

        // Frame bounding clip check limits before plotting dots on radar asset
        if (Math.hypot(pX - radarCenterX, pY - radarCenterY) < radarSize - 1) {
            ctx.fillStyle = ent.type === 'cell' ? "#00ff88" : "#ff2255"; // Green Cells vs Red Drones
            ctx.fillRect(pX - 1.5, pY - 1.5, 3, 3);
        }
    });

    // Plot Airlock Door Target Position once core harvest limits are matched
    let gateRelX = (EXIT_TILE_X + 0.5) - player.x;
    let gateRelY = (EXIT_TILE_Y + 0.5) - player.y;
    let gateRotX = gateRelX * player.dirY - gateRelY * player.dirX;
    let gateRotY = gateRelX * player.dirX + gateRelY * player.dirY;
    let gX = radarCenterX + gateRotX * 3.5;
    let gY = radarCenterY - gateRotY * 3.5;

    if (Math.hypot(gX - radarCenterX, gY - radarCenterY) < radarSize - 1) {
        ctx.fillStyle = player.cellsCollected >= 3 ? "#ffff00" : "rgba(255,153,0,0.3)"; // Glowing Unlock Orange vs Translucent Locked Yellow
        ctx.fillRect(gX - 2, gY - 2, 4, 4);
    }

    // Center Reference Point Node (Player Location Vector Position)
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(radarCenterX - 1, radarCenterY - 1, 2, 2);
}

// --- Frame Pipeline Controller ---
function gameLoop(timestamp) {
    if (gameState !== 'PLAYING') return;

    let dt = (timestamp - lastTime) / 1000.0;
    lastTime = timestamp;

    if(dt > 0.1) dt = 0.1;
    elapsedPlayTime += dt;

    accumulatedTime += dt;
    if (accumulatedTime >= 1.0) {
        oxygenTimer--;
        accumulatedTime -= 1.0;

        // Automated Safety Check Evaluation Rules
        if (oxygenTimer === 60 && !warn60Triggered) { warn60Triggered = true; dispatchVocalWarning(); }
        if (oxygenTimer === 30 && !warn30Triggered) { warn30Triggered = true; dispatchVocalWarning(); }

        if (oxygenTimer <= 0) {
            triggerEndgame(false, "Life support systems fully expired. Suffocation complete.");
            return;
        }
    }

    updateSimulation(dt);
    renderFrame();

    requestAnimationFrame(gameLoop);
}
</script>
</body>
</html>

