        wrapper.addEventListener('click', (e) => {
            if (gameState === 'PLAYING' && !e.target.classList.contains('util-btn')) {
                firePulseWeapon();
            }
        });

        // Touch Input Bindings
        function bindTouch(id, keyProp) {
            const btn = document.getElementById(id);
            if (!btn) return;
            btn.addEventListener('touchstart', (e) => { e.preventDefault(); keys[keyProp] = true; }, {passive: false});
            btn.addEventListener('touchend', (e) => { e.preventDefault(); keys[keyProp] = false; }, {passive: false});
        }
        bindTouch('btn-forward', 'w');
        bindTouch('btn-back', 's');
        bindTouch('btn-left', 'a');
        bindTouch('btn-right', 'd');
        bindTouch('btn-rotleft', 'rotLeft');
        bindTouch('btn-rotright', 'rotRight');

        document.getElementById('btn-fire').addEventListener('touchstart', (e) => {
            e.preventDefault();
            if (gameState === 'PLAYING') firePulseWeapon();
        }, {passive: false});

        // Setup Screen Transitions Binds
        document.getElementById('btn-start-game').addEventListener('click', () => {
            document.getElementById('briefing-screen').style.display = 'none';
            initLevel();
        });

        document.getElementById('btn-retry').addEventListener('click', () => {
            document.getElementById('scorecard-screen').style.display = 'none';
            initLevel();
        });

        document.getElementById('btn-mute').addEventListener('click', () => {
            audio.muted = !audio.muted;
            document.getElementById('btn-mute').textContent = audio.muted ? '🔇' : '🔊';
        });

        document.getElementById('btn-pause').addEventListener('click', togglePause);
        document.getElementById('btn-restart').addEventListener('click', initLevel);

        function togglePause() {
            if (gameState === 'PLAYING') {
                gameState = 'PAUSED';
                document.getElementById('pause-indicator').style.display = 'flex';
            } else if (gameState === 'PAUSED') {
                gameState = 'PLAYING';
                document.getElementById('pause-indicator').style.display = 'none';
                lastTime = performance.now();
                requestAnimationFrame(gameLoop);
            }
        }

        function initLevel() {
            // Restore structural lock map state
            worldMap[8][13] = 2;

            player.x = 1.5;
            player.y = 1.5;
            player.dirX = 1.0;
            player.dirY = 0.0;
            player.planeX = 0.0;
            player.planeY = 0.66;
            player.cellsCollected = 0;
            player.hull = 100;

            timeLeft = maxTime;
            dronesDisabledCount = 0;
            weaponPulseTimer = 0;
            warn60Triggered = false;
            warn30Triggered = false;

            items = JSON.parse(JSON.stringify(initialItems));
            drones = JSON.parse(JSON.stringify(initialDrones));

            updateHUD();
            document.getElementById('warning-banner').style.display = 'none';
            document.getElementById('pause-indicator').style.display = 'none';

            gameState = 'PLAYING';
            lastTime = performance.now();
            requestAnimationFrame(gameLoop);
        }

        function updateHUD() {
            document.getElementById('hud-cells').textContent = `CELLS: ${player.cellsCollected}/3`;
            document.getElementById('hud-timer').textContent = `OXYGEN: ${Math.max(0, timeLeft).toFixed(1)}s`;
            document.getElementById('hud-integrity').textContent = `SUIT: ${player.hull}%`;
            document.getElementById('hud-drones').textContent = `DRONES: ${dronesDisabledCount} X`;
        }

        function rotatePlayer(angle) {
            let oldDirX = player.dirX;
            player.dirX = player.dirX * Math.cos(angle) - player.dirY * Math.sin(angle);
            player.dirY = oldDirX * Math.sin(angle) + player.dirY * Math.cos(angle);
            let oldPlaneX = player.planeX;
            player.planeX = player.planeX * Math.cos(angle) - player.planeY * Math.sin(angle);
            player.planeY = oldPlaneX * Math.sin(angle) + player.planeY * Math.cos(angle);
        }

        // Weapon Discharge Mechanics
        function firePulseWeapon() {
            if (weaponPulseTimer > 0) return; // Fire rate limit clamp
            weaponPulseTimer = weaponPulseDuration;
            audio.fire();

            // Hitscan computation across viewing ray vector
            // Target the center screen slice (relative sprite coordinate conversion)
            let closestDrone = null;
            let closestDist = 100.0;

            drones.forEach(drone => {
                if (!drone.active) return;

                let spriteX = drone.x - player.x;
                let spriteY = drone.y - player.y;

                let invDet = 1.0 / (player.planeX * player.dirY - player.dirX * player.planeY);
                let transformX = invDet * (player.dirY * spriteX - player.dirX * spriteY);
                let transformY = invDet * (-player.planeY * spriteX + player.planeX * spriteY);

                // Ensure drone is positioned within forward clipping cone viewport bounds
                if (transformY > 0) {
                    let spriteScreenX = Math.floor((canvas.width / 2) * (1 + transformX / transformY));
                    let halfWidth = Math.abs(Math.floor(canvas.height / transformY)) / 2;

                    let screenLeft = spriteScreenX - halfWidth;
                    let screenRight = spriteScreenX + halfWidth;
                    let midScreen = canvas.width / 2;

                    // Validate center point intersections within targeting slice thresholds
                    if (midScreen >= screenLeft && midScreen <= screenRight) {
                        if (transformY < closestDist) {
                            closestDist = transformY;
                            closestDrone = drone;
                        }
                    }
                }
            });

            if (closestDrone && closestDist < 5.0) {
                // Apply damage profile metrics
                closestDrone.hp--;
                closestDrone.speed *= 0.5; // Dampen velocity on impacts

                if (closestDrone.hp <= 0) {
                    closestDrone.active = false;
                    dronesDisabledCount++;
                    audio.droneKill();
                } else {
                    audio.droneHit();
                }
            }
        }

        function flashDamageUI() {
            const flasher = document.getElementById('damage-flash');
            flasher.style.background = 'rgba(255, 0, 0, 0.4)';
            setTimeout(() => {
                flasher.style.background = 'rgba(255, 0, 0, 0)';
            }, 80);
        }

        // --- Core Simulation Engine Loop ---
        function gameLoop(timestamp) {
            if (gameState !== 'PLAYING') return;

            let dt = (timestamp - lastTime) / 1000;
            if (dt > 0.1) dt = 0.1; 
            lastTime = timestamp;

            updateSimulation(dt, timestamp);
            renderRaycaster();

            requestAnimationFrame(gameLoop);
        }

        function updateSimulation(dt, timestamp) {
            // Oxygen countdown constraints checking
            timeLeft -= dt;
            if (timeLeft <= 0) {
                timeLeft = 0;
                endGame(false, 'OXYGEN EXPIRATION');
                return;
            }

            // Time warning milestones triggers
            if (timeLeft <= 60.0 && !warn60Triggered) {
                warn60Triggered = true;
                audio.warning();
            }
            if (timeLeft <= 30.0 && !warn30Triggered) {
                warn30Triggered = true;
                audio.warning();
            }

            if (weaponPulseTimer > 0) {
                weaponPulseTimer -= dt;
            }

            // Navigation inputs
            const moveSpeed = 3.2 * dt;
            const rotSpeed = 2.4 * dt;

            let moveX = 0;
            let moveY = 0;

            if (keys.w) { moveX += player.dirX * moveSpeed; moveY += player.dirY * moveSpeed; }
            if (keys.s) { moveX -= player.dirX * moveSpeed; moveY -= player.dirY * moveSpeed; }
            if (keys.a) { moveX += player.dirY * moveSpeed; moveY -= player.dirX * moveSpeed; }
            if (keys.d) { moveX -= player.dirY * moveSpeed; moveY += player.dirX * moveSpeed; }

            let targetX = player.x + moveX;
            let targetY = player.y + moveY;

            // X and Y grid navigation slide checks
            if (worldMap[Math.floor(player.y)][Math.floor(targetX)] === 0) player.x = targetX;
            if (worldMap[Math.floor(targetY)][Math.floor(player.x)] === 0) player.y = targetY;

            // Exit zone trigger check
            if (worldMap[Math.floor(player.y)][Math.floor(player.x)] === 0 && Math.floor(player.y) === 8 && Math.floor(player.x) === 13) {
                endGame(true, 'EVACUATION TERMINAL ACCESS SUCCESS');
                return;
            }

            // Keyboard/Button based turning rotation passes
            let currentRot = 0;
            if (keys.ArrowLeft || keys.q || keys.rotLeft) currentRot -= rotSpeed;
            if (keys.ArrowRight || keys.e || keys.rotRight) currentRot += rotSpeed;
            if (currentRot !== 0) rotatePlayer(currentRot);

            // Item pickups logic evaluation
            items.forEach(item => {
                if (item.active && item.type === 'cell') {
                    let dx = player.x - item.x;
                    let dy = player.y - item.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 0.45) {
                        item.active = false;
                        player.cellsCollected++;
                        audio.pickup();

                        // Condition validation to handle dynamic airlock release
                        if (player.cellsCollected === 3) {
                            worldMap[8][13] = 0; // Airlock safely transitions to open/walkable space
                            audio.unlock();
                        }
                    }
                }
            });

            // Drone AI execution block
            let droneWarning = false;
            drones.forEach(drone => {
                if (!drone.active) return;

                let nextX = drone.x + drone.dirX * drone.speed * dt;
                let nextY = drone.y + drone.dirY * drone.speed * dt;

                if (worldMap[Math.floor(drone.y)][Math.floor(nextX)] !== 0) drone.dirX *= -1;
                else drone.x = nextX;

                if (worldMap[Math.floor(nextY)][Math.floor(drone.x)] !== 0) drone.dirY *= -1;
                else drone.y = nextY;

                let dist = Math.sqrt((player.x - drone.x)**2 + (player.y - drone.y)**2);
                if (dist < 2.0) droneWarning = true;

                if (dist < 0.52 && timestamp - drone.lastHit > 1200) {
                    drone.lastHit = timestamp;
                    player.hull -= 20;
                    audio.hit();
                    flashDamageUI();
                    if (player.hull <= 0) {
                        player.hull = 0;
                        endGame(false, 'SUIT STRUCTURE DECOMPRESSION');
                    }
                }
            });

            document.getElementById('warning-banner').style.display = droneWarning ? 'block' : 'none';
            updateHUD();
        }

        // --- Raycaster Render System & Radar Matrix ---
        function renderRaycaster() {
            const w = canvas.width;
            const h = canvas.height;

            // Canvas resets
            ctx.fillStyle = '#06060c'; ctx.fillRect(0, 0, w, h / 2);
            ctx.fillStyle = '#0c0c12'; ctx.fillRect(0, h / 2, w, h / 2);

            let zBuffer = new Array(w);

            for (let x = 0; x < w; x++) {
                let cameraX = 2 * x / w - 1;
                let rayDirX = player.dirX + player.planeX * cameraX;
                let rayDirY = player.dirY + player.planeY * cameraX;

                let mapX = Math.floor(player.x);
                let mapY = Math.floor(player.y);

                let sideDistX, sideDistY;
                let deltaDistX = (rayDirX === 0) ? 1e30 : Math.abs(1 / rayDirX);
                let deltaDistY = (rayDirY === 0) ? 1e30 : Math.abs(1 / rayDirY);
                let perpWallDist;

                let stepX, stepY;
                let hit = 0;
                let side;
                let hitType = 0;

                if (rayDirX < 0) { stepX = -1; sideDistX = (player.x - mapX) * deltaDistX; } 
                else { stepX = 1; sideDistX = (mapX + 1.0 - player.x) * deltaDistX; }
                if (rayDirY < 0) { stepY = -1; sideDistY = (player.y - mapY) * deltaDistY; } 
                else { stepY = 1; sideDistY = (mapY + 1.0 - player.y) * deltaDistY; }

                while (hit === 0) {
                    if (sideDistX < sideDistY) { sideDistX += deltaDistX; mapX += stepX; side = 0; } 
                    else { sideDistY += deltaDistY; mapY += stepY; side = 1; }
                    if (worldMap[mapY][mapX] > 0) { hit = 1; hitType = worldMap[mapY][mapX]; }
                }

                if (side === 0) perpWallDist = (sideDistX - deltaDistX);
                else           perpWallDist = (sideDistY - deltaDistY);

                if (perpWallDist <= 0) perpWallDist = 0.01;
                zBuffer[x] = perpWallDist;

                let lineHeight = Math.floor(h / perpWallDist);
                let drawStart = -lineHeight / 2 + h / 2;
                let drawEnd = lineHeight / 2 + h / 2;

                let color;
                if (hitType === 2) {
                    color = side === 1 ? '#991b1b' : '#cc2424'; 
                } else {
                    color = side === 1 ? '#14532d' : '#166534'; 
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(x, drawStart); ctx.lineTo(x, drawEnd); ctx.stroke();
            }

            // Processing array stack for drawing item and drone sprites
            let spriteArray = [];
            items.forEach(item => { if(item.active) spriteArray.push(item); });
            drones.forEach(drone => { if(drone.active) spriteArray.push(drone); });

            spriteArray.sort((a, b) => {
                let distA = (player.x - a.x)**2 + (player.y - a.y)**2;
                let distB = (player.x - b.x)**2 + (player.y - b.y)**2;
                return distB - distA;
            });

            spriteArray.forEach(sprite => {
                let spriteX = sprite.x - player.x;
                let spriteY = sprite.y - player.y;

                let invDet = 1.0 / (player.planeX * player.dirY - player.dirX * player.planeY);
                let transformX = invDet * (player.dirY * spriteX - player.dirX * spriteY);
                let transformY = invDet * (-player.planeY * spriteX + player.planeX * spriteY);

                if (transformY > 0) {
                    let spriteScreenX = Math.floor((w / 2) * (1 + transformX / transformY));
                    let spriteHeight = Math.abs(Math.floor(h / transformY));
                    let drawStartY = -spriteHeight / 2 + h / 2;
                    let spriteWidth = Math.abs(Math.floor(h / transformY));
                    let drawStartX = -spriteWidth / 2 + spriteScreenX;
                    let drawEndX = spriteWidth / 2 + spriteScreenX;

                    for (let stripe = drawStartX; stripe < drawEndX; stripe++) {
                        if (stripe >= 0 && stripe < w && transformY < zBuffer[stripe]) {
                            if (sprite.type === 'cell') {
                                ctx.fillStyle = '#00e5ff';
                                ctx.fillRect(stripe, drawStartY + (spriteHeight * 0.25), 1, spriteHeight * 0.5);
                            } else {
                                // Render active security drone mechanics with a localized health indicator bar
                                ctx.fillStyle = '#ff3131';
                                ctx.fillRect(stripe, drawStartY + (spriteHeight * 0.15), 1, spriteHeight * 0.5);

                                // Health indicator pipeline pass
                                if (stripe === Math.floor((drawStartX + drawEndX)/2)) {
                                    let barW = spriteWidth * 0.5;
                                    ctx.fillStyle = '#444';
                                    ctx.fillRect(stripe - barW/2, drawStartY - 10, barW, 3);
                                    ctx.fillStyle = '#39ff14';
                                    ctx.fillRect(stripe - barW/2, drawStartY - 10, barW * (sprite.hp / sprite.maxHp), 3);
                                }
                            }
                        }
                    }
                }
            });

            // Weapon EMP Feedback Ring render overlay pass
            if (weaponPulseTimer > 0) {
                let intensity = weaponPulseTimer / weaponPulseDuration;
                ctx.strokeStyle = `rgba(0, 229, 255, ${intensity})`;
                ctx.lineWidth = 6 * intensity;
                ctx.beginPath();
                ctx.arc(w / 2, h / 2 + 40, 40 + (1.0 - intensity) * 80, 0, Math.PI * 2);
                ctx.stroke();

                // Crosshair hit indicator element
                ctx.fillStyle = 'rgba(0, 229, 255, 0.8)';
                ctx.fillRect(w / 2 - 2, h / 2 - 2, 4, 4);
            }

            renderRadarOverlay(w, h);
        }

        function renderRadarOverlay(w, h) {
            let radarScale = 5;
            let pad = 15;
            let rw = MAP_WIDTH * radarScale;
            let rh = MAP_HEIGHT * radarScale;
            let rx = w - rw - pad;
            let ry = pad + 55;

            ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
            ctx.fillRect(rx - 4, ry - 4, rw + 8, rh + 8);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
            ctx.strokeRect(rx - 4, ry - 4, rw + 8, rh + 8);

            for (let y = 0; y < MAP_HEIGHT; y++) {
                for (let x = 0; x < MAP_WIDTH; x++) {
                    if (worldMap[y][x] === 1) {
                        ctx.fillStyle = '#1e3a1e';
                        ctx.fillRect(rx + x * radarScale, ry + y * radarScale, radarScale - 1, radarScale - 1);
                    } else if (worldMap[y][x] === 2) {
                        ctx.fillStyle = '#7f1d1d';
                        ctx.fillRect(rx + x * radarScale, ry + y * radarScale, radarScale - 1, radarScale - 1);
                    }
                }
            }

            items.forEach(item => {
                if (item.active) {
                    ctx.fillStyle = '#00e5ff';
                    ctx.fillRect(rx + Math.floor(item.x) * radarScale + 1, ry + Math.floor(item.y) * radarScale + 1, radarScale - 2, radarScale - 2);
                }
            });

            drones.forEach(drone => {
                if (drone.active) {
                    ctx.fillStyle = '#ff3131';
                    ctx.fillRect(rx + Math.floor(drone.x) * radarScale + 1, ry + Math.floor(drone.y) * radarScale + 1, radarScale - 2, radarScale - 2);
                }
            });

            // Localized Player tracking vector node
            ctx.fillStyle = '#39ff14';
            ctx.beginPath();
            ctx.arc(rx + player.x * radarScale, ry + player.y * radarScale, 2, 0, Math.PI * 2);
            ctx.fill();
        }

        // --- End Game Scorecard Generation ---
        function endGame(isVictory, technicalReason) {
            gameState = 'ENDED';

            const screen = document.getElementById('scorecard-screen');
            const headline = document.getElementById('score-headline');

            if (isVictory) {
                headline.textContent = "MISSION ACCOMPLISHED";
                headline.style.color = "var(--neon-green)";
            } else {
                headline.textContent = `MISSION FAILED: ${technicalReason}`;
                headline.style.color = "var(--neon-red)";
            }

            // Populate the fully restored 5-part scorecard rows exactly
            document.getElementById('score-time').textContent = `${(maxTime - timeLeft).toFixed(1)} SECONDS`;
            document.getElementById('score-oxy').textContent = `${timeLeft.toFixed(1)}s RESIDUAL`;
            document.getElementById('score-suit').textContent = `${player.hull}% EXTANT`;
            document.getElementById('score-cells').textContent = `${player.cellsCollected} / 3 SECTOR CORES`;
            document.getElementById('score-drones').textContent = `${dronesDisabledCount} SENTINELS REBOOTED`;

            screen.style.display = 'flex';
        }
    </script>
</body>
</html>

